steps.text:
//--- VIOC specops_multi: varias operaciones a la vez (lobby VIOC_SPECOPS_MAX_ACTIVE: por bando para la IA y por jugador
//--- para los pedidos); los topes de soldados crecen con ese maximo.
VIOC_SO_MAXACTIVE = missionNamespace getVariable ["VIOC_SPECOPS_MAX_ACTIVE", 5];
if !(VIOC_SO_MAXACTIVE isEqualType 0) then {VIOC_SO_MAXACTIVE = 5};
VIOC_SO_MAXACTIVE = ((round VIOC_SO_MAXACTIVE) max 1) min 20;
VIOC_SO_MAXUNITS = 10 * VIOC_SO_MAXACTIVE;	//--- no se lanza otra si el bando ya tiene mas soldados especiales vivos (10 por operacion)
VIOC_SO_ACTIVE = [false, false];	//--- [oeste, este]: true si el bando ya tiene el maximo de operaciones a la vez
VIOC_SO_OPS = [[], []];				//--- operaciones de la IA en curso por bando: [token, inicio, pueblo objetivo]
VIOC_SO_TOKEN = [-1, -1];			//--- (sin uso desde specops_multi: los tokens estan en VIOC_SO_OPS)
VIOC_SO_START = [0, 0];				//--- (sin uso desde specops_multi)

steps.anchor:
if ((VIOC_SO_TOKEN select _i) isEqualTo _tok) then {
	VIOC_SO_ACTIVE set [_i, false];
	VIOC_SO_TOKEN set [_i, -1];
};

steps.text:
//--- VIOC specops_multi: quita esa operacion de la lista del bando (puede haber varias a la vez)
VIOC_SO_OPS set [_i, (VIOC_SO_OPS select _i) select {!((_x select 0) isEqualTo _tok)}];
call VIOC_fnc_soSync;

steps.anchor:
VIOC_SO_ACTIVE set [_i, true];
VIOC_SO_TOKEN set [_i, _tok];
VIOC_SO_START set [_i, time];

steps.text:
//=====================================================================================================================
//--- VIOC specops_multi: varias operaciones especiales a la vez.
//---   IA: hasta VIOC_SO_MAXACTIVE operaciones en curso por bando (VIOC_SO_OPS: [token, inicio, pueblo] por bando);
//---       entre dos lanzamientos sigue habiendo como minimo VIOC_SPECOPS_INTERVAL minutos (igual que antes).
//---       VIOC_SO_ACTIVE [oeste, este] = true solo cuando el bando ya tiene el maximo (el gestor no lanza mas).
//---       Un pueblo no es objetivo de dos operaciones del mismo bando a la vez (VIOC_fnc_soBusyTowns).
//---   Jugadores: hasta VIOC_SO_MAXACTIVE pedidos activos por jugador (VIOC_SO_PREQ: [uid, token, inicio, ayudante,
//---       pueblo, bando]); el recuento de cada jugador se publica en VIOC_SO_PREQ_N ([uid, n], ...) para su panel.
//---   Topes de soldados: IA 10 x maximo por bando (VIOC_SO_MAXUNITS), pedidos 8 x maximo por bando
//---   (VIOC_SO_PREQ_SIDECAP); el presupuesto de IA (VIOC_PERF_AI_MAX) se sigue respetando.
//--- Consola (servidor): VIOC_SO_OPS   operaciones de la IA en curso;   VIOC_SO_PREQ   pedidos de jugadores en curso
//=====================================================================================================================

//--- VIOC_SO_ACTIVE de cada bando = ya tiene el maximo de operaciones a la vez.
VIOC_fnc_soSync = {
	{VIOC_SO_ACTIVE set [_forEachIndex, (count _x) >= VIOC_SO_MAXACTIVE]} forEach VIOC_SO_OPS;
};

//--- Pueblos que ya son objetivo de una operacion en curso del bando (de la IA o pedida por un jugador).
VIOC_fnc_soBusyTowns = {
	params ["_side"];
	private _i = [_side] call VIOC_fnc_soSideID;
	private _res = [];
	if (_i >= 0) then {{_res pushBackUnique (_x param [2, objNull])} forEach (VIOC_SO_OPS select _i)};
	{if ((_x param [5, sideUnknown]) isEqualTo _side) then {_res pushBackUnique (_x param [4, objNull])}} forEach VIOC_SO_PREQ;
	_res - [objNull]
};

//--- La operacion avanzo a otro pueblo: se anota como su nuevo objetivo.
VIOC_fnc_soOpSetTown = {
	params ["_tok", "_town"];
	if (_tok isEqualType "") exitWith {{if ((_x select 1) isEqualTo _tok) then {_x set [4, _town]}} forEach VIOC_SO_PREQ};
	{
		{if ((_x select 0) isEqualTo _tok) then {_x set [2, _town]}} forEach _x;
	} forEach VIOC_SO_OPS;
};

//--- Pedidos en curso de un jugador (los colgados se liberan solos a la hora y media de empezar, como el vigilante).
VIOC_fnc_soPreqCount = {
	params ["_uid"];
	{[_x select 1] call VIOC_fnc_soPreqFree} forEach (VIOC_SO_PREQ select {((_x select 0) == _uid) && {(time - (_x select 2)) > (VIOC_SO_LIFETIME + 3000)}});
	{(_x select 0) == _uid} count VIOC_SO_PREQ
};

//--- Publica a los clientes cuantos pedidos en curso tiene cada jugador (para "pedidos activos X/N" del panel).
VIOC_fnc_soPreqPublish = {
	private _uids = [];
	{_uids pushBackUnique (_x select 0)} forEach VIOC_SO_PREQ;
	VIOC_SO_PREQ_N = _uids apply {private _u = _x; [_u, {(_x select 0) == _u} count VIOC_SO_PREQ]};
	publicVariable "VIOC_SO_PREQ_N";
};
VIOC_SO_PREQ_N = [];
publicVariable "VIOC_SO_PREQ_N";
format ["varias a la vez: hasta %1 operaciones por bando (IA) y por jugador; topes de soldados IA %2 y pedidos %3 por bando", VIOC_SO_MAXACTIVE, VIOC_SO_MAXUNITS, VIOC_SO_PREQ_SIDECAP] call VIOC_fnc_soLog;

steps.anchor:
//--- vigilante: si el script de una operacion muriera sin liberar a su bando, se libera a la hora y media
{
	if ((VIOC_SO_ACTIVE select _x) && {(time - (VIOC_SO_START select _x)) > (VIOC_SO_LIFETIME + 3000)}) then {
		VIOC_SO_ACTIVE set [_x, false];
		VIOC_SO_TOKEN set [_x, -1];
		VIOC_SO_LAST set [_x, "liberado por el vigilante (la operacion no termino)"];
		"vigilante: operacion colgada, bando liberado" call VIOC_fnc_soLog;
	};
} forEach [0, 1];

steps.text:
//--- vigilante (VIOC specops_multi: por operacion): si el script de una operacion muriera sin liberarla, se quita a la hora y media
{
	private _i = _x;
	private _ops = VIOC_SO_OPS select _i;
	private _keep = _ops select {(time - (_x select 1)) <= (VIOC_SO_LIFETIME + 3000)};
	if (count _keep < count _ops) then {
		VIOC_SO_OPS set [_i, _keep];
		VIOC_SO_LAST set [_i, format ["liberadas por el vigilante: %1 (no terminaron)", (count _ops) - (count _keep)]];
		"vigilante: operacion colgada, liberada" call VIOC_fnc_soLog;
	};
} forEach [0, 1];
call VIOC_fnc_soSync;

//--- VIOC specops_multi: pedidos tuyos en curso (lo publica el servidor en VIOC_SO_PREQ_N) y maximo a la vez.
VIOC_SOR_fnc_active = {
	private _uid = getPlayerUID player;
	if (_uid == "") then {_uid = "local"};
	private _l = missionNamespace getVariable ["VIOC_SO_PREQ_N", []];
	private _i = if (_l isEqualType []) then {_l findIf {_x isEqualType [] && {(_x param [0, ""]) == _uid}}} else {-1};
	private _max = (missionNamespace getVariable ["VIOC_SO_PREQ_CFG", []]) param [5, 1];
	if !(_max isEqualType 0) then {_max = 1};
	[if (_i < 0) then {0} else {(_l select _i) param [1, 0]}, _max]
};

(call VIOC_SOR_fnc_active) params ["_act", "_maxAct"];	//--- VIOC specops_multi
_l pushBack format ["<t color='#9fd3ff'>Pedidos activos:</t> <t color='%3'>%1/%2</t>", _act, _maxAct, if (_act >= _maxAct) then {"#F56363"} else {"#76F563"}];
_l pushBack (if (_cd > 0) then {format ["<t color='#9fd3ff'>Espera entre pedidos:</t> <t color='#F5D363'>faltan %1 s</t>", round _cd]} else {"<t color='#9fd3ff'>Espera entre pedidos:</t> <t color='#76F563'>lista</t>"});

